using Servicio.RetazoMarket.Business.DTOs.ProveedorMaterial;
namespace Servicio.RetazoMarket.Business.Validators;
public static class ProveedorMaterialValidator { public static IReadOnlyCollection<string> Validar(CrearProveedorMaterialRequest r)=>r is null?["La solicitud no puede ser nula."]:Campos(r.id_material,r.id_proveedor,r.origen,r.precio_compra,r.cantidad_min,r.dias_entrega); public static IReadOnlyCollection<string> Validar(ActualizarProveedorMaterialRequest r)=>r is null?["La solicitud no puede ser nula."]:Campos(r.id_material,r.id_proveedor,r.origen,r.precio_compra,r.cantidad_min,r.dias_entrega); private static IReadOnlyCollection<string> Campos(int m,int p,string? o,decimal precio,int cantidad,int dias){var e=new List<string>();if(m<=0)e.Add("El material es obligatorio.");if(p<=0)e.Add("El proveedor es obligatorio.");if(o?.Trim().ToUpperInvariant() is not("NAC" or "IMP"))e.Add("El origen debe ser NAC o IMP.");if(precio<0)e.Add("El precio de compra no puede ser negativo.");if(decimal.Round(precio,2)!=precio)e.Add("El precio de compra admite máximo dos decimales.");if(cantidad<=0)e.Add("La cantidad mínima debe ser mayor que cero.");if(dias<0)e.Add("Los días de entrega no pueden ser negativos.");return e;} }
